long long computeMinCost(long long n, long long k, vector<long long>& l) {
    vector<long long> l1(n);
    fill(l1.begin(), l1.end(), 0);

    for (int i = 1; i < n; i++) {
        l1[i] = l1[i - 1] + abs(l[i - 1] - l[i]);
        for (int j = 1; j <= min(i * 1LL, k); j++) {
